package com.avrgaming.civcraft.modern.diplomacy;
import java.sql.*;
import java.time.*;
import com.avrgaming.civcraft.modern.war.*;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;
class WarDeclarationRulesTest {
    final DiplomacyStoreTest f=new DiplomacyStoreTest();final WarCalendar calendar=new WarCalendar(7,10,120,3,24,ZoneId.of("UTC"));
    long at(int day,int hour){return ZonedDateTime.of(2026,10,day,hour,0,0,0,ZoneId.of("UTC")).toInstant().toEpochMilli();}
    Connection database()throws Exception {var db=f.database();db.createStatement().execute("ALTER TABLE civilizations ADD COLUMN debt INTEGER NOT NULL DEFAULT 0");AdminCivilizationStore.install(db);WarClockStore.install(db);db.commit();return db;}
    void ally(Connection db)throws Exception {db.createStatement().execute("INSERT INTO civilizations(id,leader_uuid) VALUES(3,'"+f.b+"')");db.createStatement().execute("INSERT INTO diplomacy_relations VALUES(1,3,'ALLY',NULL,0),(2,3,'WAR',2,0)");db.commit();}
    DiplomacyStore.Relation declare(Connection db,long now)throws Exception {return WarDeclarationRules.declare(db,1,2,f.a,DiplomacyStore.Status.WAR,calendar,false,now);}
    @Test void ordinaryDeclarationChangesBothSidesSetsDeclarerAggressorAndCancelsOldOffer()throws Exception {try(var db=database()){DiplomacyStore.request(db,1,2,f.a,DiplomacyStore.Status.ALLY,at(12,10));db.commit();var relation=declare(db,at(12,10)+1);db.commit();assertEquals(DiplomacyStore.Status.WAR,DiplomacyStore.status(db,2,1));assertEquals(1,relation.aggressor());assertNull(DiplomacyStore.incoming(db,2,at(12,10)+2));assertThrows(IllegalArgumentException.class,()->declare(db,at(12,10)+2));}}
    @Test void roleDebtCasualAndAdministrativeTargetChecksHaveNoOperatorBypass()throws Exception {try(var db=database()){assertThrows(IllegalArgumentException.class,()->WarDeclarationRules.declare(db,1,2,f.member,DiplomacyStore.Status.WAR,calendar,false,at(12,10)));assertThrows(IllegalArgumentException.class,()->WarDeclarationRules.declare(db,1,2,f.a,DiplomacyStore.Status.WAR,calendar,true,at(12,10)));db.createStatement().execute("UPDATE civilizations SET debt=1 WHERE id=1");assertThrows(IllegalArgumentException.class,()->declare(db,at(12,10)));assertDoesNotThrow(()->WarDeclarationRules.declare(db,1,2,f.a,DiplomacyStore.Status.HOSTILE,calendar,false,at(12,10)));db.rollback();db.createStatement().execute("INSERT INTO administrative_civilizations VALUES(2)");assertThrows(IllegalArgumentException.class,()->declare(db,at(12,10)));assertThrows(IllegalArgumentException.class,()->WarDeclarationRules.declare(db,1,2,f.a,DiplomacyStore.Status.HOSTILE,calendar,false,at(12,10)));}}
    @Test void closeWindowAllowsOnlyDefendingAllyAgainstTheActualAggressor()throws Exception {try(var db=database()){assertThrows(IllegalArgumentException.class,()->declare(db,at(14,12)));ally(db);assertTrue(WarDeclarationRules.helpsAlly(db,1,2));assertEquals(1,declare(db,at(14,12)).aggressor());db.rollback();db.createStatement().execute("UPDATE diplomacy_relations SET aggressor=3 WHERE first_civ=2 AND second_civ=3");assertFalse(WarDeclarationRules.helpsAlly(db,1,2));assertThrows(IllegalArgumentException.class,()->declare(db,at(14,12)));}}
    @Test void exactTwentyFourHoursAllowsAllyHelpButOneMillisecondLaterDoesNot()throws Exception {try(var db=database()){ally(db);assertDoesNotThrow(()->declare(db,at(16,10)));db.rollback();assertThrows(IllegalArgumentException.class,()->declare(db,at(16,10)+1));}}
    @Test void activeAndUnprocessedExpiredBattleFencesDiplomacy()throws Exception {try(var db=database()){long now=at(12,10);db.createStatement().execute("INSERT INTO war_sessions VALUES("+(now-1000)+","+(now+1000)+",'ACTIVE')");db.commit();assertThrows(IllegalArgumentException.class,()->declare(db,now));assertThrows(IllegalArgumentException.class,()->declare(db,now+2000));}}
    @Test void advisorCanDeclareAndRollbackRestoresStatusAndAudit()throws Exception {try(var db=database()){db.createStatement().execute("INSERT INTO civ_advisors VALUES(1,'"+f.member+"')");db.commit();WarDeclarationRules.declare(db,1,2,f.member,DiplomacyStore.Status.WAR,calendar,false,at(12,10));db.rollback();assertEquals(DiplomacyStore.Status.NEUTRAL,DiplomacyStore.status(db,1,2));try(var r=db.createStatement().executeQuery("SELECT COUNT(*) FROM diplomacy_audit")){r.next();assertEquals(0,r.getInt(1));}}}
}
